import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address payable caller) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        try c.play{value: 10}() {
            // play succeeded
        } catch {
            // revert is possible (e.g., if caller is bank), but state unchanged
        }
        uint256 potAfter = c.pot();
        assertTrue(potAfter == 0 || potAfter == 10);
    }
}

